class Solution:
    def transformTree(self, root):
        def reverse_inorder(node, acc):
            if not node:
                return acc
            acc = reverse_inorder(node.right, acc)
            node.data = acc = acc + node.data
            acc = reverse_inorder(node.left, acc)
            return acc

        reverse_inorder(root, 0)
